#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5
REPOSITORY_ROOT=$(cd "$(dirname "$0")/.." && pwd -P)
ROOT_ORCHESTRATOR=/usr/local/libexec/voice-agent

show_difference() {
  local label=$1 reviewed=$2 pinned=$3 expected_mode=${4:-}
  local actual_mode= content_matches=false mode_matches=true
  if ! sudo test -e "$pinned"; then
    warn "$label is absent from the pinned authority."
    sudo diff -u --label "pinned/$label" --label "reviewed/$label" \
      /dev/null "$reviewed" || true
  else
    if sudo cmp -s "$reviewed" "$pinned"; then
      content_matches=true
    fi
    if [[ -n $expected_mode ]]; then
      actual_mode=$(sudo stat -c %a "$pinned" 2>/dev/null) || actual_mode=
      actual_mode="0$actual_mode"
      if [[ $actual_mode != "$expected_mode" ]]; then mode_matches=false; fi
    fi
    if [[ $content_matches == true && $mode_matches == true ]]; then
      note "$label is already pinned at the reviewed version."
      return
    fi
    printf '\n  %s%s%s\n' "$BOLD" "$label" "$RESET"
    if [[ $content_matches != true ]]; then
      sudo diff -u --label "pinned/$label" --label "reviewed/$label" \
        "$pinned" "$reviewed" || true
    fi
    if [[ $mode_matches != true ]]; then
      warn "$label has pinned mode $actual_mode; the reviewed manifest publishes $expected_mode."
    fi
  fi
}

show_removal() {
  local label=$1 pinned=$2
  warn "$label is pinned but absent from the reviewed manifest; it will be removed."
  sudo diff -u --label "pinned/$label" --label "reviewed/$label" \
    "$pinned" /dev/null || true
}

reviewed_manifest_contains() {
  local candidate=$1 reviewed
  for reviewed in "${reviewed_authority_paths[@]}"; do
    if [[ $candidate == "$reviewed" ]]; then return 0; fi
  done
  return 1
}

if [[ ! -f $REPOSITORY_ROOT/.voice-agent-release ]]; then
  warn "Run this wizard from the active immutable Agent Host Release."
  exit 1
fi
MERGED_COMMIT=$(<"$REPOSITORY_ROOT/.voice-agent-release")
if [[ ! $MERGED_COMMIT =~ ^[0-9a-f]{40}$ ]] || \
  [[ $(readlink -f /opt/voice-agent/current) != "$REPOSITORY_ROOT" ]]; then
  warn "The wizard source is not the active immutable Agent Host Release."
  exit 1
fi

banner "Voice Agent deployment-authority upgrade"

stage "Verify the reviewed active Release"
say "Only the exact active Release from the latest successful Human Merge may update root-pinned deployment authority."
# shellcheck source=release/release-immutability.sh
source "$REPOSITORY_ROOT/ops/release/release-immutability.sh"
if [[ $(sudo stat -c %U "$REPOSITORY_ROOT") != root ]]; then
  warn "The active Release is not root-owned."
  exit 1
fi
if ! voice_agent_release_tree_is_immutable "$REPOSITORY_ROOT"; then
  warn "The active Release has writable content or a symlink that escapes its immutable tree."
  exit 1
fi
if ! sudo awk -F '\t' -v commit="$MERGED_COMMIT" \
  '$2 == commit { found=1 } END { exit !found }' \
  /var/lib/voice-agent-promotions/verified-human-merges.tsv; then
  warn "The active Release has no root-owned verified Human Merge transition."
  exit 1
fi
note "Reviewed active Release: $MERGED_COMMIT"
pause "Confirm the Release identity, then press Enter."

stage "Review the pinned-authority differences"
say "Review every script, verifier, systemd definition, and AppArmor profile that this attended action will pin. No credential values are read or displayed."
# shellcheck source=release/deployment-authority-manifest.sh
source "$REPOSITORY_ROOT/ops/release/deployment-authority-manifest.sh"
reviewed_authority_paths=()
for script in "${voice_agent_authority_scripts[@]}"; do
  reviewed_authority_paths+=("$script")
  show_difference "$script" "$REPOSITORY_ROOT/ops/release/$script" \
    "$ROOT_ORCHESTRATOR/$script"
done
for unit in "${voice_agent_authority_units[@]}"; do
  reviewed_authority_paths+=("systemd/$unit")
  show_difference "$unit" "$REPOSITORY_ROOT/ops/systemd/$unit" \
    "$ROOT_ORCHESTRATOR/systemd/$unit"
done
for mapping in "${voice_agent_authority_apparmor_profiles[@]}"; do
  source_path=${mapping%%:*}
  target_path=${mapping#*:}
  reviewed_authority_paths+=("apparmor/$target_path")
  show_difference "AppArmor $target_path" \
    "$REPOSITORY_ROOT/$source_path" \
    "$ROOT_ORCHESTRATOR/apparmor/$target_path"
done
for mapping in "${voice_agent_authority_programs[@]}"; do
  source_path=${mapping%%:*}
  target_path=${mapping#*:}
  published_mode=${mapping##*:}
  target_path=${target_path%%:*}
  reviewed_authority_paths+=("$target_path")
  show_difference "$target_path" "$REPOSITORY_ROOT/$source_path" \
    "$ROOT_ORCHESTRATOR/$target_path" "$published_mode"
done
for mapping in "${voice_agent_authority_extras[@]}"; do
  source_path=${mapping%%:*}
  target_path=${mapping#*:}
  reviewed_authority_paths+=("$target_path")
  show_difference "$target_path" "$REPOSITORY_ROOT/$source_path" \
    "$ROOT_ORCHESTRATOR/$target_path"
done
while IFS= read -r pinned; do
  relative=${pinned#"$ROOT_ORCHESTRATOR/"}
  if ! reviewed_manifest_contains "$relative"; then
    show_removal "$relative" "$pinned"
  fi
done < <(sudo find "$ROOT_ORCHESTRATOR" \( -type f -o -type l \) -print | sort)
pause "Review the complete authority diff, then press Enter."

stage "Authorize the expansion with a Fresh Passkey Action"
say "Terminal access and a Human Merge are not authority-expansion credentials. Root prepares a five-minute challenge bound to this exact active commit; a PWA request has no authority until the pinned verifier accepts its passkey proof."
NEEDS_ROOT_PASSKEY_ENROLLMENT=false
if ! sudo test -f \
  /var/lib/voice-agent-deployment-authority/authorization-credentials.json; then
  NEEDS_ROOT_PASSKEY_ENROLLMENT=true
  note "First use: root will show the existing owner-passkey labels, credential IDs, and public-key fingerprints as untrusted enrollment candidates."
fi
sudo "$REPOSITORY_ROOT/ops/release/upgrade-deployment-authority.sh" \
  --prepare "$MERGED_COMMIT"
if [[ $NEEDS_ROOT_PASSKEY_ENROLLMENT == true ]]; then
  say "This one-time authenticated out-of-band step is your root approval of the existing owner credentials shown above. Stop if any label, credential, or fingerprint is unexpected. Approval alone grants no deployment authority."
  confirm "Do the displayed candidates identify your existing owner passkeys?" || exit 1
fi
open_url "https://voice.stephens.page"
step "Sign in and choose “Create deployment-authority Fresh Passkey proof”."
step "Authenticate one of the approved existing owner passkeys before the challenge expires. Stop if no authenticator prompt appears."
pause "Confirm the PWA submitted a proof for commit $MERGED_COMMIT, then press Enter."
if [[ $NEEDS_ROOT_PASSKEY_ENROLLMENT == true ]]; then
  sudo "$REPOSITORY_ROOT/ops/release/upgrade-deployment-authority.sh" \
    --enroll "$MERGED_COMMIT"
  sudo "$REPOSITORY_ROOT/ops/release/upgrade-deployment-authority.sh" \
    --prepare "$MERGED_COMMIT"
  step "Choose “Create deployment-authority Fresh Passkey proof” again and authenticate the newly root-enrolled existing credential."
  pause "Confirm the PWA submitted the separate assertion for commit $MERGED_COMMIT, then press Enter."
fi

stage "Upgrade and activate the reviewed authority"
say "The root helper consumes the narrow Fresh Passkey request, stages the exact reviewed manifest and AppArmor profile, retains the prior authority, and restores both if activation or health verification fails."
confirm "Consume the authorization and activate Release $MERGED_COMMIT?" || exit 1
sudo "$REPOSITORY_ROOT/ops/release/upgrade-deployment-authority.sh" \
  --activate "$MERGED_COMMIT"

stage "Verify the restricted Subagent boundary"
say "The upgraded promoter must provision the restricted Subagent and pass the complete Agent Host health contract."
sudo cmp -s "$REPOSITORY_ROOT/ops/release/promote-release.sh" \
  "$ROOT_ORCHESTRATOR/promote-release.sh"
sudo cmp -s "$REPOSITORY_ROOT/ops/systemd/voice-agent-subagent.service" \
  "$ROOT_ORCHESTRATOR/systemd/voice-agent-subagent.service"
for mapping in "${voice_agent_authority_apparmor_profiles[@]}"; do
  source_path=${mapping%%:*}
  profile=${mapping#*:}
  sudo cmp -s "$REPOSITORY_ROOT/$source_path" \
    "$ROOT_ORCHESTRATOR/apparmor/$profile"
  sudo cmp -s "$ROOT_ORCHESTRATOR/apparmor/$profile" \
    "/etc/apparmor.d/$profile"
done
sudo test "$(sudo cat /proc/sys/kernel/apparmor_restrict_unprivileged_userns)" = 1
sudo grep -q '^bwrap (enforce)$' /sys/kernel/security/apparmor/profiles
sudo grep -q '^unpriv_bwrap (enforce)$' \
  /sys/kernel/security/apparmor/profiles
sudo systemctl is-active --quiet voice-agent-subagent.service
sudo "$ROOT_ORCHESTRATOR/deployment-health.sh"
note "Next: cd /opt/voice-agent/current && ./ops/acceptance/run-keeplore-button-trial.sh"
pause "The reviewed deployment authority and restricted Subagent are active."

finish
